package com.decimal128.textcodec.tests

import com.decimal128.textcodec.Decimal128TextCodec

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue
import kotlin.test.fail

/**
 * The four conformance tables, over the shared `text_bid_dpd` corpus.
 *
 * The vectors are read straight out of `resources/text_bid_dpd` -- the
 * `decimal128-resources` submodule -- and were generated by the `decimal128-c`
 * engine through its public API. That engine reaches its answers by different
 * algorithms than this codec does, so agreement is a cross-check rather than a
 * tautology.
 *
 *   T1 DECODE  bid -> text and dpd -> text          (100, noncanonical)
 *   T2 ENCODE  text -> bid and text -> dpd          (100)
 *   T3 PARSE   input text -> bits, both formats     (parse, 1,061 rows)
 *   T4 ERROR   malformed input text -> rejection    (error, 173 rows)
 *
 * Plus the cross-format assertion: for every row both encodings must render to
 * the same text. That is the strongest property the corpus encodes.
 *
 * The fifth table, `canonical`, is 84,783 rows of mostly common-path volume and
 * runs as [TestCanonicalCorpus], the second class in this file.
 */
class TestCorpusVectors {

    /** T1: every row's two encodings must render to the expected text. */
    @Test
    fun hundredDecodes() {
        val rows = Corpus.load(Corpus.HUNDRED)
        assertEquals(100, rows.size)
        runDecodeTable(rows, "100")
    }

    /** T2: and the text must encode back to the same bits. */
    @Test
    fun hundredReEncodes() {
        val rows = Corpus.load(Corpus.HUNDRED)
        assertEquals(100, rows.size)
        runEncodeTable(rows, "100")
    }

    /**
     * One-way rows: both encodings decode to the text, but at least one is a bit
     * pattern the canonical encoder would never emit, so re-encoding is
     * deliberately not asserted.
     */
    @Test
    fun nonCanonicalEncodingsRenderCorrectly() {
        val rows = Corpus.load(Corpus.NON_CANONICAL)
        assertEquals(1267, rows.size)
        runDecodeTable(rows, "noncanonical")
    }

    /** T3: the only table that reaches the rounding surface at all. */
    @Test
    fun parseVectorsProduceBothEncodings() {
        val rows = Corpus.load(Corpus.PARSE)
        assertEquals(1061, rows.size)
        for (row in rows) {
            val b = bidParse(row.text)
            assertNull(b.error, "parse line " + row.lineNumber + ": bid rejected <" + row.text + ">")
            assertEquals(row.bidHex, b.hex, "parse line " + row.lineNumber + ": bid <" + row.text + ">")
            val d = dpdParse(row.text)
            assertNull(d.error, "parse line " + row.lineNumber + ": dpd rejected <" + row.text + ">")
            assertEquals(row.dpdHex, d.hex, "parse line " + row.lineNumber + ": dpd <" + row.text + ">")
        }
    }

    /**
     * T4: malformed input. Both formats must reject, must agree on the message,
     * and must still have written the canonical positive quiet NaN -- the corpus
     * carries that pattern in its bits columns precisely so a port can assert the
     * written value and not merely the rejection.
     */
    @Test
    fun errorVectorsAreRejectedByBothFormats() {
        val rows = Corpus.load(Corpus.ERROR)
        assertEquals(173, rows.size)
        for (row in rows) {
            val b = bidParse(row.text)
            val d = dpdParse(row.text)
            assertNotNull(b.error,
                "error line " + row.lineNumber + ": bid ACCEPTED <" + row.text + ">, corpus says " + row.status)
            assertNotNull(d.error,
                "error line " + row.lineNumber + ": dpd ACCEPTED <" + row.text + ">, corpus says " + row.status)
            assertEquals(b.error, d.error,
                "error line " + row.lineNumber + ": the formats disagree on <" + row.text + ">")
            assertEquals(row.status, b.error,
                "error line " + row.lineNumber + ": <" + row.text + "> disagrees with the corpus status")
            assertEquals(row.bidHex, b.hex, "error line " + row.lineNumber + ": bid <" + row.text + ">")
            assertEquals(row.bidHex, d.hex, "error line " + row.lineNumber + ": dpd <" + row.text + ">")
        }
    }

    /**
     * The reader itself. `parse` and `error` quote their text column, and the
     * four rows below are exactly the ones a naive comma split corrupts while
     * still passing -- a mangled malformed input fails to parse either way.
     */
    @Test
    fun quotedColumnRoundTrips() {
        val texts = Corpus.load(Corpus.ERROR).map { it.text }.toSet()
        assertTrue(texts.contains(""), "the empty-string row was lost")
        assertTrue(texts.any { it.startsWith(" ") }, "a leading-space row was lost")
        assertTrue(texts.any { it.endsWith(" ") }, "a trailing-space row was lost")
        assertTrue(texts.any { it.contains(",") }, "an embedded-comma row was lost")
    }
}

/**
 * Every row: both encodings must render to the expected text, and
 * therefore to each other.
 */
private fun runDecodeTable(rows: List<CorpusRow>, label: String) {
    val buf = ByteArray(Decimal128TextCodec.MAX_LEN)
    for (row in rows) {
        assertEquals(row.text, Decimal128TextCodec.bid128ToString(row.bidHi, row.bidLo),
            label + " line " + row.lineNumber + ": bid #" + row.bidHex)
        assertEquals(row.text, Decimal128TextCodec.dpd128ToString(row.dpdHi, row.dpdLo),
            label + " line " + row.lineNumber + ": dpd #" + row.dpdHex)
        val bidLen = Decimal128TextCodec.bid128ToAscii(buf, row.bidHi, row.bidLo)
        assertEquals(row.text, buf.decodeToString(0, bidLen),
            label + " line " + row.lineNumber + ": bid into buffer #" + row.bidHex)
        val dpdLen = Decimal128TextCodec.dpd128ToAscii(buf, row.dpdHi, row.dpdLo)
        assertEquals(row.text, buf.decodeToString(0, dpdLen),
            label + " line " + row.lineNumber + ": dpd into buffer #" + row.dpdHex)
    }
}

/** Round-trippable rows: the text must encode back to the same bits. */
private fun runEncodeTable(rows: List<CorpusRow>, label: String) {
    for (row in rows) {
        val b = bidParse(row.text)
        assertNull(b.error, label + " line " + row.lineNumber + ": bid rejected <" + row.text + ">")
        assertEquals(row.bidHex, b.hex, label + " line " + row.lineNumber + ": bid <" + row.text + ">")
        val d = dpdParse(row.text)
        assertNull(d.error, label + " line " + row.lineNumber + ": dpd rejected <" + row.text + ">")
        assertEquals(row.dpdHex, d.hex, label + " line " + row.lineNumber + ": dpd <" + row.text + ">")
    }
}

/**
 * The full canonical table: 84,783 rows, read from the same submodule as the
 * rest. It is a separate class only because it is two orders of magnitude bigger
 * than the other four put together, not because it is optional -- keeping it
 * here rather than in a file of its own is what lets the two table runners above
 * stay private to this file.
 *
 * These rows were out of reach while the corpus was transcribed into Kotlin
 * source -- at that density they would have been some 7 MB of it.
 */
class TestCanonicalCorpus {

    @Test
    fun canonicalTableDecodesAndReEncodes() {
        val rows = Corpus.load(Corpus.CANONICAL)
        assertEquals(84783, rows.size)
        runDecodeTable(rows, "canonical")
        runEncodeTable(rows, "canonical")
    }
}

/**
 * One row of a `text_bid_dpd` table: the text, the two encodings as 32 bare
 * uppercase hex digits, and the `status` column the input-driven tables carry.
 */
class CorpusRow(
    val text: String,
    val bidHex: String,
    val dpdHex: String,
    val status: String,
    val lineNumber: Int,
) {
    val bidHi: Long get() = hi(bidHex)
    val bidLo: Long get() = lo(bidHex)
    val dpdHi: Long get() = hi(dpdHex)
    val dpdLo: Long get() = lo(dpdHex)
}

/** The high word of a 32-digit hex encoding. */
fun hi(h: String): Long = h.substring(0, 16).toULong(16).toLong()

/** The low word of a 32-digit hex encoding. */
fun lo(h: String): Long = h.substring(16, 32).toULong(16).toLong()

/** An encoding rendered the way the corpus spells it: 32 uppercase hex digits. */
fun hex(a: Long, b: Long): String =
    a.toULong().toString(16).padStart(16, '0').uppercase() +
        b.toULong().toString(16).padStart(16, '0').uppercase()

// The one KMP seam in this repo's tests, and the reason it lives here rather
// than in a file of its own: `expect` and its only caller are both `commonTest`,
// so the declaration sits with the reader that uses it, the way the C, Swift,
// Java and C# ports keep their loaders with theirs. Only the `actual`s need
// files of their own -- one per platform family, because they are three
// different APIs in three different source sets.
//
// The conformance corpus lives in decimal128-resources, mounted as a submodule at
// <repo>/resources -- the same mount every decimal128 port uses. commonTest has
// no portable file access, so reaching it needs an actual per platform family:
// the JVM and native read the filesystem directly, Node reads it through `fs`.
// Each one resolves an absolute base from the DECIMAL128_RESOURCES environment
// variable, which the build sets on every test task; the desktop actuals also
// accept the relative path a Gradle test task's working directory gives them.
//
// fileName is corpus-root-relative with a leading '/', e.g.
// "/text_bid_dpd/text_bid128_dpd128_100.csv.txt". Returns null when the file is
// not there, which for this repo means the submodule is not checked out.
expect fun loadTestResourceAsString(fileName: String): String?

/** Where the loader looked, for an error message that names the fix. */
const val RESOURCES_HINT: String =
    "the decimal128-resources submodule is not checked out: " +
        "run `git submodule update --init --recursive`"

/**
 * The shared conformance corpus, read from `resources/text_bid_dpd` -- the
 * `decimal128-resources` submodule, mounted at the repo root the way every
 * decimal128 port mounts it. Nothing is copied into this repo.
 *
 * These vectors used to be transcribed into Kotlin source, because `commonTest`
 * has no portable file access and a data file would have needed a reader per
 * target. That reader now exists ([loadTestResourceAsString]), so every target
 * reads the tables themselves -- which also brings the 84,783-row `canonical`
 * table within reach, at 10 MB far past what transcription could carry.
 *
 * The row counts are asserted by the tests, and that is not ceremony: the text
 * column of `parse` and `error` is double-quoted with `\\` and `\"` escapes,
 * because those tables must carry the empty string, a leading and a trailing
 * space, an embedded comma, an embedded quote and an embedded backslash. The
 * other three leave it bare. A naive comma split silently corrupts four rows and
 * still passes, since a mangled malformed input fails to parse either way. The
 * row count is what catches it.
 */
object Corpus {

    const val DIRECTORY: String = "/text_bid_dpd"

    const val HUNDRED: String = "text_bid128_dpd128_100"
    const val NON_CANONICAL: String = "text_bid128_dpd128_noncanonical"
    const val PARSE: String = "text_bid128_dpd128_parse"
    const val ERROR: String = "text_bid128_dpd128_error"
    const val CANONICAL: String = "text_bid128_dpd128_canonical"

    /** One table, read through the platform loader. */
    fun load(name: String): List<CorpusRow> {
        val path = DIRECTORY + "/" + name + ".csv.txt"
        val contents = loadTestResourceAsString(path)
            ?: fail(path + " could not be read -- " + RESOURCES_HINT)
        return parseTable(contents, name)
    }

    private fun parseTable(contents: String, name: String): List<CorpusRow> {
        val rows = ArrayList<CorpusRow>()
        var lineNumber = 0
        for (rawLine in contents.split('\n')) {
            ++lineNumber
            var line = rawLine
            while (line.endsWith("\r")) {
                line = line.dropLast(1)
            }
            line = skipSpace(line)
            if (line.isEmpty() || line.startsWith("#")) {
                continue
            }

            val text: String
            if (line.startsWith("\"")) {
                val quoted = readQuoted(line)
                text = quoted.first
                line = quoted.second
            } else {
                val bare = readField(line)
                text = bare.first
                line = bare.second
            }
            val bid = readNextField(line)
            val dpd = readNextField(bid.second)
            val status = readNextField(dpd.second)

            val bidHex = normalizeHex(bid.first)
            val dpdHex = normalizeHex(dpd.first)
            if ((bidHex == null) || (dpdHex == null)) {
                fail(name + ".csv.txt line " + lineNumber + ": malformed hex columns <" +
                    bid.first + "> <" + dpd.first + ">")
            }
            rows.add(CorpusRow(text, bidHex, dpdHex, status.first, lineNumber))
        }
        return rows
    }

    /** `0x` + 32 hex digits, or 32 bare ones, normalized to bare uppercase. */
    private fun normalizeHex(field: String): String? {
        val body = if (field.startsWith("0x") || field.startsWith("0X")) field.substring(2) else field
        if (body.length != 32) {
            return null
        }
        for (c in body) {
            if (!((c in '0'..'9') || (c in 'a'..'f') || (c in 'A'..'F'))) {
                return null
            }
        }
        return body.uppercase()
    }

    // -- the reader, matching the C and Swift ports ---------------------------

    private fun skipSpace(s: String): String {
        var i = 0
        while ((i < s.length) && ((s[i] == ' ') || (s[i] == '\t'))) {
            ++i
        }
        return s.substring(i)
    }

    /**
     * One comma-delimited field, stopping at `,` or `#` or end of line, with
     * surrounding whitespace trimmed. Returns the field and the unconsumed rest.
     */
    private fun readField(s: String): Pair<String, String> {
        val start = skipSpace(s)
        var end = 0
        while ((end < start.length) && (start[end] != ',') && (start[end] != '#')) {
            ++end
        }
        var trim = end
        while ((trim > 0) && ((start[trim - 1] == ' ') || (start[trim - 1] == '\t'))) {
            --trim
        }
        return Pair(start.substring(0, trim), start.substring(end))
    }

    /**
     * Step over a field separator, then read the next field. Yields the empty
     * string when the row has no further column.
     */
    private fun readNextField(s: String): Pair<String, String> {
        val rest = skipSpace(s)
        if (!rest.startsWith(",")) {
            return Pair("", rest)
        }
        return readField(rest.substring(1))
    }

    /** The quoted text column, honouring `\\` and `\"` escapes. */
    private fun readQuoted(s: String): Pair<String, String> {
        val out = StringBuilder()
        var i = 1 // past the opening quote
        while ((i < s.length) && (s[i] != '"')) {
            var c = s[i]
            ++i
            if ((c == '\\') && (i < s.length)) {
                c = s[i]
                ++i
            }
            out.append(c)
        }
        if ((i < s.length) && (s[i] == '"')) {
            ++i
        }
        return Pair(out.toString(), s.substring(i))
    }
}

// ---------------------------------------------------------------------------
// Thin wrappers so the tests read the way the codec's own API does.
// ---------------------------------------------------------------------------

class ParseResult(val hex: String, val error: String?)

fun bidParse(text: String): ParseResult {
    val bits = longArrayOf(0xFEEDL, 0xFACEL)
    val err = Decimal128TextCodec.bid128Parse(bits, text)
    return ParseResult(hex(bits[0], bits[1]), err)
}

fun dpdParse(text: String): ParseResult {
    val bits = longArrayOf(0xFEEDL, 0xFACEL)
    val err = Decimal128TextCodec.dpd128Parse(bits, text)
    return ParseResult(hex(bits[0], bits[1]), err)
}
